let pendingStateSync = false;
let lastSavedActivityKey = '';
let pendingSyncAction = 'Inventory changes';
const pendingStateKey = 'godown-pending-state';
const persistPendingState = () => {
	try {
		localStorage.setItem(pendingStateKey, JSON.stringify({products, movements:activity, priceHistory, suppliers, customers, viewUsers, salesOrders}));
		localStorage.setItem('godown-pending-sync', 'pending');
	} catch(error) {
		console.warn('[stock] Could not persist pending sync state.', error);
	}
};
const restorePendingState = () => {
	if (!localStorage.getItem('godown-pending-sync')) return false;
	try {
		const state = JSON.parse(localStorage.getItem(pendingStateKey) || '{}');
		if (Array.isArray(state.products)) products = state.products;
		if (Array.isArray(state.movements)) activity = state.movements;
		if (Array.isArray(state.priceHistory)) priceHistory = state.priceHistory;
		if (Array.isArray(state.suppliers)) suppliers = state.suppliers;
		if (Array.isArray(state.customers)) customers = state.customers;
		if (Array.isArray(state.viewUsers)) viewUsers = state.viewUsers;
		if (Array.isArray(state.salesOrders)) salesOrders = state.salesOrders;
		pendingStateSync = true;
		stockLog('Restored pending local state for Firebase retry');
		return true;
	} catch(error) {
		console.warn('[stock] Pending sync state could not be restored.', error);
		return false;
	}
};
