const signInUser=(username,password)=>{if(username==='admin'&&password==='admin123')return 'admin';if(username==='superadmin'&&password==='SuperAdmin@123')return 'superadmin';const user=viewUsers.find(item=>item.username===username&&item.password===password);return user?'viewer':null};
