async function loadServerState(){if(!firebaseUser){stockLog('Firestore sync waiting for anonymous auth');return}try{stockLog('Starting realtime listener',sharedInventoryRef.path);onSnapshot(sharedInventoryRef,snapshot=>{if(replacingInventory){stockLog('Ignoring old snapshot during Excel replacement');return}const state=snapshot.exists()?snapshot.data():{};stockLog('Realtime snapshot received',{exists:snapshot.exists(),products:(state.products||[]).length});sharedStateReady=true;setSyncStatus('synced');if(pendingStateSync&&canEdit()){saveFirebaseState().catch(error=>console.error('[stock] pending Firestore save failed',error));}else if(snapshot.exists()){products=state.products||[];activity=state.movements||[];priceHistory=state.priceHistory||priceHistory;suppliers=state.suppliers||suppliers;customers=state.customers||customers;viewUsers=state.viewUsers||viewUsers;if(Array.isArray(state.salesOrders))salesOrders=state.salesOrders;localStorage.setItem('godown-products',JSON.stringify(products));localStorage.setItem('godown-activity',JSON.stringify(activity));localStorage.setItem('godown-price-history',JSON.stringify(priceHistory));localStorage.setItem('godown-suppliers',JSON.stringify(suppliers));localStorage.setItem('godown-customers',JSON.stringify(customers));localStorage.setItem('godown-view-users',JSON.stringify(viewUsers));localStorage.setItem('godown-sales-orders',JSON.stringify(salesOrders));}else if(canEdit()&&(products.length||activity.length||priceHistory.length||suppliers.length||customers.length||salesOrders.length)){saveFirebaseState().catch(error=>console.error('[stock] initial Firestore upload failed',error))}if(currentRole){document.querySelector('#login-screen').classList.add('hidden');document.querySelector('.app-shell').classList.add('ready');render()}} ,error=>{setSyncStatus('retry pending');console.error('[stock] realtime Firebase listener failed',error)})}catch(error){setSyncStatus('retry pending');console.error('[stock] Firestore listener setup failed',error)}}
async function saveFirebaseState(){if(!canEdit()||!firebaseUser||!sharedStateReady||skipNextStateSync){stockLog('Firestore save skipped',{role:currentRole,hasUser:Boolean(firebaseUser),ready:sharedStateReady,skipped:skipNextStateSync});if(!navigator.onLine)setSyncStatus('offline · pending');return}pendingFirebaseWrite=true;setSyncStatus('syncing...');stockLog('Saving shared inventory',{products:products.length,movements:activity.length});try{await setDoc(sharedInventoryRef,{products,movements:activity,priceHistory,suppliers,customers,viewUsers,salesOrders,updatedAt:new Date().toISOString()},{merge:true});pendingStateSync=false;localStorage.removeItem('godown-pending-sync');localStorage.removeItem(pendingStateKey);replacingInventory=false;setSyncStatus('synced');stockLog('Shared inventory saved');const latest=activity[0];const activityKey=latest?`${latest.createdAt||latest.time}|${latest.type}|${latest.product||''}|${latest.items?.length||''}`:'';if(activityKey&&activityKey!==lastSavedActivityKey){lastSavedActivityKey=activityKey;const label=latest.type==='out'?'Sale saved':latest.type==='in'?'Stock in saved':latest.type==='edit'?'Product changes saved':latest.type==='delete'?'Product deleted':'Changes saved';showToast(`${label} · Shared inventory saved`,'success')}}catch(error){persistPendingState();setSyncStatus('retry pending');replacingInventory=false;console.error('[stock] Firestore save failed',error);showToast('Could not save to shared inventory. It will retry when connected.','error');throw error}finally{pendingFirebaseWrite=false;replacingInventory=false}}
document.querySelector('#login-form').addEventListener('submit',event=>{event.preventDefault();event.stopImmediatePropagation();const username=document.querySelector('#login-username').value.trim().toLowerCase(),password=document.querySelector('#login-password').value,role=signInUser(username,password);if(!role){document.querySelector('#login-error').textContent='Invalid username or password.';return}currentRole=role;sessionStorage.setItem('godown-role',role);document.querySelector('#login-error').textContent='';document.querySelector('#login-screen').classList.add('hidden');document.querySelector('.app-shell').classList.add('ready');render()},true);
onAuthStateChanged(auth,user=>{firebaseUser=user;stockLog('Firebase auth state changed',{anonymousUser:Boolean(user),uid:user?.uid});if(user)loadServerState().catch(error=>console.error('[stock] realtime sync unavailable',error))});
document.querySelector('#logout-button').addEventListener('click',()=>document.querySelector('.app-shell').classList.remove('ready'));
const $ = (q) => document.querySelector(q);
document.querySelector('#movement-form').addEventListener('submit',()=>{skipNextStateSync=true;const product=products.find(p=>p.id===Number(document.querySelector('#product-select').value)),before=product?.stock,quantity=Number(document.querySelector('#quantity').value);setTimeout(()=>{if(activity[0]&&activity[0].type&&before!==undefined){activity[0].beforeStock=before;activity[0].afterStock=product.stock;activity[0].stockChange=quantity;save();render()}},0)},true);
let pendingDeleteId=null;
document.addEventListener('click',e=>{const edit=e.target.closest('[data-edit-product]'),remove=e.target.closest('[data-delete-product]');if(edit&&canEdit()){const p=products.find(item=>item.id===Number(edit.dataset.editProduct));if(p)openProductModal(p)}if(remove&&canEdit()){const p=products.find(item=>item.id===Number(remove.dataset.deleteProduct));if(p){pendingDeleteId=p.id;$('#delete-product-description').textContent=`${p.name} · ${p.category||'Uncategorized'} · ${p.variant} currently has ${p.stock} pieces.`;$('#delete-modal').classList.remove('hidden')}}});
document.querySelector('#product-form').addEventListener('submit',e=>{if(!editingProductId)return;e.preventDefault();e.stopImmediatePropagation();const p=products.find(item=>item.id===editingProductId);if(p){const before=`${p.name} · ${p.category||'Uncategorized'} · ${p.code} · ${p.variant} · ${p.stock} pcs`;p.name=$('#new-name').value.trim();p.category=$('#new-category').value.trim();p.code=$('#new-code').value.trim()||p.code;p.variant=$('#new-variant').value.trim();p.stock=Math.max(0,Number($('#new-stock').value));p.price=Number($('#new-price').value) || 0;p.min=Math.max(0,Number($('#new-min').value));const after=`${p.name} · ${p.category} · ${p.code} · ${p.variant} · ${p.stock} pcs`;activity.unshift({type:'edit',product:p.name,variant:p.variant,before,after,time:'Just now'});save();editingProductId=null;$('#product-modal').classList.add('hidden');render()}},true);
$('#close-delete-modal').onclick=()=>$('#delete-modal').classList.add('hidden');$('#confirm-delete').onclick=()=>{if(pendingDeleteId!==null&&canEdit()){const removed=products.find(item=>item.id===pendingDeleteId);products=products.filter(item=>item.id!==pendingDeleteId);activity.unshift({type:'delete',product:removed.name,variant:removed.variant,qty:removed.stock,ref:`Deleted by ${currentRole==='superadmin'?'Super Admin':currentRole==='admin'?'Owner':'Entry Staff'}`,time:'Just now'});pendingDeleteId=null;save();$('#delete-modal').classList.add('hidden');render()}};
const totalStock = () => products.reduce((sum,p)=>sum+p.stock,0);
const lowStock = () => products.filter(p=>p.stock<=p.min);
const formatTime = value => value === 'Just now' ? 'Just now' : new Date(value).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'});
const money = value => `₹${Number(value||0).toLocaleString('en-IN')}`;
let pendingTelegramActivityKey='';
async function notifyTelegram(text,idempotencyKey=''){const notificationKey=idempotencyKey||pendingTelegramActivityKey;pendingTelegramActivityKey='';const endpoint=location.hostname==='localhost'||location.hostname==='127.0.0.1'?'/api/telegram/notify':'/.netlify/functions/telegram-notify';const message=String(text).includes('STOCK RECEIVED / PURCHASE')?String(text).replaceAll('Remaining:','After Stock:').replace('📥 Total Remaining:','📈 After Stock:'):text;try{const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:message,idempotencyKey:notificationKey})}),result=await response.json().catch(()=>({}));if(!response.ok||result.sent!==true)throw new Error(result.error||`Telegram endpoint returned ${response.status}`);stockLog(result.duplicate?'Telegram duplicate suppressed':`Telegram notification sent${result.parts>1?` in ${result.parts} parts`:''}`);return true}catch(error){console.warn('[stock] Telegram notification unavailable.',error);return false;}}
function productTelegramText(action,product,extra=''){return `Godown Stock Log\nAction: ${action}\nProduct: ${product.name}\nCategory: ${product.category||'Uncategorized'}\nSKU: ${product.code||'-'}\nSize / Variant: ${product.variant||'-'}\nPrice: ${money(product.price)}/pc\nStock: ${product.stock} pcs${extra?`\n${extra}`:''}\nDate: ${new Date().toLocaleString('en-IN')}\nBy: ${currentRole==='admin'?'Owner':'Entry Staff'}`;}
let lastTelegramActivityKey = '';
let lastSavedActivityCount = activity.length;
function notifyLatestActivity(){const item=activity[0];if(!item)return;const key=`${item.createdAt||item.time}|${item.type}|${item.product}|${item.variant}|${item.qty||''}|${item.items?.length||''}`;if(key===lastTelegramActivityKey)return;lastTelegramActivityKey=key;if(item.items?.length){const isSale=item.type==='out',action=isSale?'SALE / STOCK DISPATCHED':'STOCK RECEIVED / PURCHASE',lines=item.items.map((line,index)=>{const before=Number(line.beforeStock)||0,quantity=Number(line.qty)||0,remaining=Number(line.afterStock)||0;return `${index+1}. ${line.name} ${line.variant||''}\n\nSKU: ${line.code||'-'}\nSize: ${line.variant||'-'}\n\nBefore Stock: ${before} pcs\n${isSale?'Dispatched':'Received'}: ${quantity} pcs\nRemaining: ${remaining} pcs\n\nRate: ${money(line.rate)}/pc\nAmount: ${money(line.amount)}`}).join('\n\n━━━━━━━━━━━━━━\n\n'),totalAmount=item.items.reduce((sum,line)=>sum+(Number(line.amount)||0),0),totalBefore=item.items.reduce((sum,line)=>sum+(Number(line.beforeStock)||0),0),totalRemaining=item.items.reduce((sum,line)=>sum+(Number(line.afterStock)||0),0);notifyTelegram(`🏭 GODOWN ${action}\n\n📅 Date: ${new Date(item.createdAt||Date.now()).toLocaleString('en-IN')}\n👤 ${isSale?'Customer':'Supplier'}: ${item.party||'-'}\n📄 Reference: ${item.reference||'-'}\n👨‍💼 By: ${currentRole==='admin'?'Owner':'Entry Staff'}\n\n━━━━━━━━━━━━━━\n\n${lines}\n\n━━━━━━━━━━━━━━\n\n📊 TOTAL\n\nTotal Items: ${item.items.length}\nTotal Quantity: ${item.qty} pcs\nTOTAL: ${money(totalAmount)}\n\n📦 Total Before Stock: ${totalBefore} pcs\n${isSale?'📤 Total Dispatched':'📥 Total Received'}: ${item.qty} pcs\n📥 Total Remaining: ${totalRemaining} pcs\n\n━━━━━━━━━━━━━━\n✅ STOCK UPDATED`);return}const product=products.find(p=>p.name===item.product&&p.variant===item.variant)||{name:item.product,category:item.category,code:item.code,variant:item.variant,price:item.price,stock:item.afterStock??item.qty??0};notifyTelegram(productTelegramText(item.type==='in'?'Stock received':item.type==='out'?'Sale / stock dispatched':item.type==='edit'?'Product edited':'Product deleted',product,`Quantity: ${item.qty||'-'} pcs\nReference: ${item.ref||item.after||'-'}`));}
function exportReport(){const rows=[['Product','Category','SKU','Size / Variant','Price per piece','Stock','Low-stock alert'],...products.map(p=>[p.name,p.category||'Uncategorized',p.code||'',p.variant||'',p.price||0,p.stock,p.min])];activity.forEach(a=>rows.push(['LOG',a.type,a.product,a.variant,a.price||0,a.qty||'',a.ref||'']));const csv=rows.map(row=>row.map(value=>`"${String(value??'').replace(/"/g,'""')}"`).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download=`godown-stock-report-${new Date().toISOString().slice(0,10)}.csv`;link.click();URL.revokeObjectURL(url);}
const originalNotifyLatestActivity=notifyLatestActivity;
notifyLatestActivity=function(){const item=activity[0];if(!item?.items?.length)return originalNotifyLatestActivity();const key=`${item.createdAt||item.time}|${item.type}|${item.product}|${item.variant}|${item.qty||''}|${item.items.length}`;if(key===lastTelegramActivityKey)return;lastTelegramActivityKey=key;const isSale=item.type==='out',action=isSale?'SALE / STOCK DISPATCHED':'STOCK RECEIVED / PURCHASE',lines=item.items.map((line,index)=>{const before=Number(line.beforeStock)||0,quantity=Number(line.qty)||0,remaining=Number(line.afterStock)||0;return `${index+1}. ${line.name} ${line.variant||''}\n\nSKU: ${line.code||'-'}\nSize: ${line.variant||'-'}\n\nBefore Stock: ${before} pcs\n${isSale?'Dispatched':'Received'}: ${quantity} pcs\nRemaining: ${remaining} pcs\n\nRate: ${money(line.rate)}/pc\nAmount: ${money(line.amount)}`}).join('\n\n━━━━━━━━━━━━━━\n\n'),totalAmount=item.items.reduce((sum,line)=>sum+(Number(line.amount)||0),0),totalBefore=item.items.reduce((sum,line)=>sum+(Number(line.beforeStock)||0),0),totalRemaining=item.items.reduce((sum,line)=>sum+(Number(line.afterStock)||0),0),saleTotals=isSale?`\n\nSubtotal: ${money(item.subtotal)}\nDiscount: ${item.discountPercent||0}% (-${money(item.discountAmount)})\nAfter discount: ${money(item.afterDiscount)}\nGST: ${money(item.gstAmount)}\nFinal total: ${money(item.finalTotal)}`:'';notifyTelegram(`🏭 GODOWN ${action}\n\n📅 Date: ${new Date(item.createdAt||Date.now()).toLocaleString('en-IN')}\n👤 ${isSale?'Customer':'Supplier'}: ${item.party||'-'}\n📄 Reference: ${item.reference||'-'}\n👨‍💼 By: ${currentRole==='admin'?'Owner':'Entry Staff'}\n\n━━━━━━━━━━━━━━\n\n${lines}\n\n━━━━━━━━━━━━━━\n\n📊 TOTAL\n\nTotal Items: ${item.items.length}\nTotal Quantity: ${item.qty} pcs\nTOTAL: ${money(totalAmount)}${saleTotals}\n\n📦 Total Before Stock: ${totalBefore} pcs\n${isSale?'📤 Total Dispatched':'📥 Total Received'}: ${item.qty} pcs\n${isSale?'📥 Total Remaining':'📈 After Stock'}: ${totalRemaining} pcs\n\n━━━━━━━━━━━━━━\n✅ STOCK UPDATED`);};
function save(){if(!canEdit())return;const activityChanged=activity.length!==lastSavedActivityCount;lastSavedActivityCount=activity.length;activity.forEach(item=>{if(!item.createdAt)item.createdAt=new Date().toISOString()});localStorage.setItem('godown-products',JSON.stringify(products));localStorage.setItem('godown-suppliers',JSON.stringify(suppliers));localStorage.setItem('godown-customers',JSON.stringify(customers));localStorage.setItem('godown-view-users',JSON.stringify(viewUsers));pendingStateSync=true;persistPendingState();const latest=activity[0];pendingSyncAction=latest?.type==='out'?'Sale':latest?.type==='in'?'Purchase':latest?.type==='edit'?'Product changes':latest?.type==='delete'?'Product deletion':'Inventory changes';setSyncStatus('syncing',pendingSyncAction);if(activityChanged&&(latest?.type==='in'||latest?.type==='out')){pendingTelegramActivityKey=`${latest.createdAt||latest.time}|${latest.type}|${latest.product}|${latest.variant}|${latest.qty||''}|${latest.items?.length||''}`;notifyLatestActivity()}if(firebaseUser&&!skipNextStateSync)saveFirebaseState().catch(error=>console.warn('Firestore save unavailable; local copy retained.',error));skipNextStateSync=false;}
function productRows(list=products){return list.map(p=>{const priceText = Number(p.price) ? ` · ₹${Number(p.price).toLocaleString('en-IN')}/pc` : '',category=(p.category||p.name||'').trim(),code=String(p.code||'').trim(),sizeMatches=String(p.variant||'').match(/\d+(?:\.\d+)?\s*(?:mm|cm|in|\")/ig)||[],shortVariant=sizeMatches.at(-1)||'',sku=/\d+(?:\.\d+)?\s*(?:mm|cm|in|\")/i.test(code)?code:[code,shortVariant].filter(Boolean).join(' '),label=sku?`${category} - ${sku}`:category; return `<tr><td class="product-cell"><span class="product-sku-line">${label}</span>${priceText?`<small>${priceText}</small>`:''}</td><td class="stock-number ${p.stock<=p.min?'stock-low':'stock-ok'}">${p.stock.toLocaleString()} pcs</td><td>${p.min} pcs</td><td><span class="pill ${p.stock<=p.min?'out':'in'}">${p.stock<=p.min?'Low stock':'In stock'}</span></td></tr>`;}).join('') || '<tr><td colspan="4" class="empty">No matching products found</td></tr>';
}
function activityRows(list=activity.slice(0,5)){return list.map(a=>{const labels={in:['Stock received','↓',''],out:['Stock dispatched','↑','out'],edit:['Product edited','✎',''],delete:['Product deleted','×','out']},label=labels[a.type]||labels.edit,groupedDetail=a.items?.length?`<br><span class="audit-change"><b>${a.type==='in'?'Department / Supplier':'Customer'}:</b> ${a.party||'-'}<br><b>Reference:</b> ${a.reference||'-'}<br>${a.items.map(item=>`${item.name} · SKU ${item.code||'-'} · ${item.qty} pcs × ${money(item.rate)}/pc`).join('<br>')}${a.summary||''}<br><b>Total:</b> ${money(a.items.reduce((sum,item)=>sum+item.amount,0))}${a.finalSummary||''}</span>`:'',movementDetail=(a.type==='in'||a.type==='out')&&a.beforeStock!==undefined?`<br><span class="audit-change"><b>Party / Reference:</b> ${a.ref||'-'}<br><b>Price:</b> ${money(a.price)}/pc<br><b>Before:</b> ${a.beforeStock} pcs<br><b>${a.type==='in'?'Added':'Dispatched'}:</b> ${a.stockChange||a.qty} pcs<br><b>After:</b> ${a.afterStock} pcs</span>`:'',editDetail=a.type==='edit'?`<br><span class="audit-change"><b>Before:</b> ${a.before}<br><b>After:</b> ${a.after}</span>`:'';return `<div class="activity-item"><div class="activity-icon ${label[2]}">${label[1]}</div><div><b>${label[0]}${a.qty?` · ${a.qty} pcs`:''}</b><p><strong class="activity-sku">${a.items?.length?`${a.items.length} SKU(s)`:`SKU: ${a.code||'-'}`}</strong><br>${a.product} · ${a.variant||''}${groupedDetail||movementDetail||editDetail||(!movementDetail&&!editDetail&&a.ref?`<br>${a.ref}`:'')}</p></div><time>${formatTime(a.createdAt||a.time)}</time></div>`}).join('') || '<div class="empty">No activity yet</div>';}
const originalActivityRows=activityRows;
activityRows=function(list=activity.slice(0,5)){const enhanced=list.map(item=>item.items?.length?({...item,summary:item.discountPercent?`<br><b>Subtotal:</b> ${money(item.subtotal)} · <b>Discount:</b> ${item.discountPercent}% (-${money(item.discountAmount)}) · <b>After discount:</b> ${money(item.afterDiscount)} · <b>GST:</b> ${money(item.gstAmount)}`:'',finalSummary:item.discountPercent?`<br><b>Final total:</b> ${money(item.finalTotal)}`:'',items:item.items.map(line=>({...line,name:`${line.name}<br><b>Category:</b> ${line.category||'Uncategorized'}<br><b>Before:</b> ${line.beforeStock??'-'} pcs · <b>${item.type==='in'?'Added':'Dispatched'}:</b> ${line.qty??0} pcs · <b>After:</b> ${line.afterStock??'-'} pcs`}))}):item);return originalActivityRows(enhanced)};
function emptyInventory(){return `<div class="empty">No products added yet. Start by entering your actual catalogue items and opening piece count.</div>`}
function movementActions(){return canEdit()?`<div><button class="primary-button" id="add-product">+ Add product</button> <button class="primary-button" id="add-purchase">Stock ↓</button> <button class="primary-button" id="add-sale" style="background:var(--orange)">Sale ↑</button> <button class="primary-button" id="add-cash-sale" style="background:#a56a20">Cash sale</button></div>`:''}
const stockHealthSummary=()=>{const low=lowStock().filter(product=>product.stock>0),out=products.filter(product=>product.stock<=0);return `<div class="stock-health-grid"><button class="stock-health-card low" type="button" data-stock-summary="low"><span><b>LOW STOCK</b><small>Below alert threshold</small></span><strong>${low.length}</strong><em>View summary →</em></button><button class="stock-health-card out" type="button" data-stock-summary="out"><span><b>OUT OF STOCK</b><small>No pieces available</small></span><strong>${out.length}</strong><em>View summary →</em></button></div>`};
function overview(){const today=new Date().toDateString();return `<section class="main-view"><div class="view-head"><div><div class="eyebrow">LIVE SNAPSHOT · SINGLE GODOWN</div><h2>Stock at a glance</h2></div>${movementActions()}</div><div class="metric-grid"><div class="metric-card"><p>TOTAL PIECES</p><strong>${totalStock().toLocaleString()}</strong><small>↑ Live count</small></div><div class="metric-card"><p>PRODUCT VARIANTS</p><strong>${products.length}</strong><small>Added by you</small></div><div class="metric-card"><p>STOCK IN · TODAY</p><strong>${activity.filter(a=>a.type==='in'&&new Date(a.createdAt||a.time).toDateString()===today).reduce((s,a)=>s+a.qty,0).toLocaleString()}</strong><small>↑ Received</small></div><div class="metric-card"><p>LOW STOCK ITEMS</p><strong>${lowStock().length}</strong><small class="trend-down">Needs attention</small></div></div><div class="metric-grid monthly-metric-grid"><div class="metric-card"><p>MONTH SALE</p><strong>${money(monthValue('out'))}</strong><small>1st to month end</small></div><div class="metric-card"><p>MONTH STOCK IN</p><strong>${money(monthValue('in'))}</strong><small>1st to month end</small></div><div class="metric-card"><p>NET CHANGE · THIS MONTH</p><strong>${signedMoney(monthNetStockValue())}</strong><small>Stock-in value minus sales</small></div></div>${stockHealthSummary()}<div class="content-grid"><div class="panel"><div class="panel-head"><h3>Current inventory</h3><a data-go="inventory">View all →</a></div><div class="table-wrap">${products.length?`<table class="data-table"><thead><tr><th>Product / variant</th><th>Available</th><th>Alert at</th><th>Status</th></tr></thead><tbody>${productRows(products.slice(0,5))}</tbody></table>`:emptyInventory()}</div></div><div class="panel"><div class="panel-head"><h3>Recent activity</h3><a data-go="activity">View log →</a></div><div class="activity-list">${activityRows()}</div></div></div></section>`}
const isExcelImport=item=>String(item.ref||'').toLowerCase().includes('excel import');
const activityValue=item=>item.items?.length?Number(item.finalTotal??item.totalAmount??item.items.reduce((sum,line)=>sum+(Number(line.amount)||((Number(line.qty)||0)*(Number(line.rate)||0))),0)):(Number(item.qty)||0)*(Number(item.transactionPrice??item.price)||0);
const localDateKey=(date=new Date())=>{const year=date.getFullYear(),month=String(date.getMonth()+1).padStart(2,'0'),day=String(date.getDate()).padStart(2,'0');return `${year}-${month}-${day}`};
const isOnLocalDate=(item,dateKey=localDateKey())=>{const date=new Date(item.createdAt||item.time);return !Number.isNaN(date.getTime())&&localDateKey(date)===dateKey};
const todayValue=(type,predicate=()=>true)=>activity.filter(item=>item.type===type&&!isExcelImport(item)&&predicate(item)&&isOnLocalDate(item)).reduce((sum,item)=>sum+activityValue(item),0);
const saleValue=(period,cash)=>period('out',item=>Boolean(item.cashSale)===cash);
const isInCurrentMonth=item=>{const date=new Date(item.createdAt||item.time),now=new Date();return !Number.isNaN(date.getTime())&&!isExcelImport(item)&&date.getFullYear()===now.getFullYear()&&date.getMonth()===now.getMonth()};
const monthValue=(type,predicate=()=>true)=>activity.filter(item=>item.type===type&&isInCurrentMonth(item)&&predicate(item)).reduce((sum,item)=>sum+activityValue(item),0);
const monthNetStockValue=()=>monthValue('in')-monthValue('out');
const monthActivity=()=>activity.filter(isInCurrentMonth);
const monthPieces=type=>monthActivity().filter(item=>item.type===type).reduce((sum,item)=>sum+(Number(item.qty)||0),0);
