function replacePurchaseLabels(root=document.querySelector('#view-container')){if(!root)return;const replace=value=>value.replace(/Purchases/g,'Stock').replace(/Purchase/g,'Stock').replace(/purchases/g,'stock').replace(/purchase/g,'stock');const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(node=>{node.nodeValue=replace(node.nodeValue)});root.querySelectorAll('input,textarea').forEach(input=>{input.value=replace(input.value);if(input.placeholder)input.placeholder=replace(input.placeholder)})}
