const restoreBackup=async event=>{const file=event.target.files?.[0];event.target.value='';if(!file||!canEdit())return;try{const data=JSON.parse(await file.text());if(!Array.isArray(data.products)||!Array.isArray(data.movements))throw new Error('Backup must contain products and movements.');if(!window.confirm(`Restore ${data.products.length} products, ${data.movements.length} movements and ${Array.isArray(data.salesOrders)?data.salesOrders.length:0} sales orders? Current data will be replaced.`))return;products=data.products;activity=data.movements;priceHistory=Array.isArray(data.priceHistory)?data.priceHistory:[];suppliers=Array.isArray(data.suppliers)?data.suppliers:[];customers=Array.isArray(data.customers)?data.customers:[];viewUsers=Array.isArray(data.viewUsers)?data.viewUsers:[];salesOrders=Array.isArray(data.salesOrders)?data.salesOrders:[];const categories=Array.isArray(data.categories)?data.categories:[];localStorage.setItem('godown-products',JSON.stringify(products));localStorage.setItem('godown-activity',JSON.stringify(activity));localStorage.setItem('godown-price-history',JSON.stringify(priceHistory));localStorage.setItem('godown-suppliers',JSON.stringify(suppliers));localStorage.setItem('godown-customers',JSON.stringify(customers));localStorage.setItem('godown-view-users',JSON.stringify(viewUsers));localStorage.setItem('godown-sales-orders',JSON.stringify(salesOrders));localStorage.setItem('godown-categories',JSON.stringify(categories));document.body.classList.toggle('dark-mode',data.darkMode===true);localStorage.setItem('godown-dark-mode',data.darkMode===true?'1':'0');pendingStateSync=true;localStorage.setItem('godown-pending-sync','pending');replacingInventory=false;render();setSyncStatus('syncing...');await saveFirebaseState();showToast('Full backup restored and synced.','success')}catch(error){console.error('[stock] backup restore failed',error);showToast(`Backup restore failed: ${error.message||'invalid JSON file.'}`,'error')}};
