additiveExcelImport=async function(event){const file=event.target.files[0]||window.pendingExcelFile;event.target.value='';window.pendingExcelFile=null;if(!file)return;if(!window.XLSX){showToast('Excel reader load nahi hua. Page refresh karke dobara try karo.','error');return}try{const workbook=XLSX.read(await file.arrayBuffer(),{type:'array'});let rows=[];for(const sheetName of workbook.SheetNames){const candidate=XLSX.utils.sheet_to_json(workbook.Sheets[sheetName],{defval:''});if(candidate.some(row=>String(findColumn(row,['product','item','productname','itemname','description'])).trim())){rows=candidate;break}}if(!rows.length){showToast('Excel mein Product column ya product rows nahi mile.','error');return}let existingCodes=new Set(products.map(product=>String(product.code||'').trim().toLowerCase()).filter(Boolean)),existingSkuVariants=new Set(products.map(product=>`${String(product.code||'').trim().toLowerCase()}|${String(product.variant||'').trim().toLowerCase()}`).filter(key=>!key.startsWith('|'))),existingIdentities=new Set(products.map(product=>`${String(product.name||'').trim().toLowerCase()}|${String(product.category||'').trim().toLowerCase()}|${String(product.variant||'').trim().toLowerCase()}`)),importedProducts=[],alreadyAvailable=0,skippedRows=0,now=Date.now();rows.forEach((row,index)=>{let name=String(findColumn(row,['product','item','productname','itemname','description'])).trim();if(!name){skippedRows++;return}let category=String(findColumn(row,['category','group','productcategory'])).trim()||'Uncategorized',code=String(findColumn(row,['code','sku','itemcode','productcode'])).trim(),variant=String(findColumn(row,['variant','size','finish','sizevariant','model'])).trim()||'Standard',stock=Math.max(0,Number(findColumn(row,['stock','qty','quantity','pieces','closingstock','openingstock']))||0),price=Math.max(0,Number(findColumn(row,['price','rate','unitprice','priceperpiece','mrp','cost']))||0),min=Math.max(0,Number(findColumn(row,['minimum','minstock','minimumstock','alert','alertat']))||0),identity=`${name.toLowerCase()}|${category.toLowerCase()}|${variant.toLowerCase()}`,isRejectionCategory=category.toLowerCase()==='rejection';if((code&&existingSkuVariants.has(`${code.toLowerCase()}|${variant.toLowerCase()}`))||(!code&&!isRejectionCategory&&existingIdentities.has(identity))){alreadyAvailable++;return}let importedProduct={id:now+index,name,category,code:code||`IMPORT-${now}-${index}`,variant,stock,price,min};products.push(importedProduct);existingCodes.add(importedProduct.code.toLowerCase());existingSkuVariants.add(`${importedProduct.code.toLowerCase()}|${variant.toLowerCase()}`);existingIdentities.add(identity);activity.unshift({type:'in',product:name,category,code:importedProduct.code,variant,price,transactionPrice:price,qty:stock,beforeStock:0,afterStock:stock,stockChange:stock,ref:'Excel import - new product',time:'Just now'});importedProducts.push(importedProduct)});if(!importedProducts.length){showToast('Excel checked: ' + rows.length + ' rows. ' + alreadyAvailable + ' already available. No products added.','info');return}replacingInventory=false;save();render();showToast('Excel checked: ' + rows.length + ' rows. ' + importedProducts.length + ' new products imported. ' + alreadyAvailable + ' already available.','success')}catch(error){console.error('[stock] Additive Excel import failed',error);showToast(`Excel import failed: ${error.message||'file format check karo.'}`,'error')}};
