const salesOrderLines = order => Array.isArray(order.items) ? order.items : [];
const salesOrderTotals = order => {
	const subtotal = salesOrderLines(order).reduce((sum, line) => sum + (Number(line.qty) || 0) * (Number(line.rate) || 0), 0);
	const discountPercent = Math.min(100, Math.max(0, Number(order.discountPercent) || 0));
	const discount = subtotal * discountPercent / 100;
	const afterDiscount = subtotal - discount;
	const gstPercent = Math.max(0, Number(order.gstPercent) || 0);
	const gst = afterDiscount * gstPercent / 100;
	return { subtotal, discount, gst, total: afterDiscount + gst };
};
