const productionExportRows = () => [['Product', 'SKU / Code', 'Required Quantity', 'Value / Item', 'Total Value'], ...selectedProductionRows().map(item => [item.product.name, item.sku, item.quantity, Number(item.product.price) || 0, item.quantity * (Number(item.product.price) || 0)]), ['Total Required', '', selectedProductionQuantity(), '', selectedProductionRows().reduce((total, item) => total + item.quantity * (Number(item.product.price) || 0), 0)]];
